function validate([operations, args]) {
  if (operations[0] !== 'SnakeGame' || !Array.isArray(args[0]) || args[0].length !== 3) return 'Start with SnakeGame(width, height, food).';
  const [width, height, food] = args[0];
  if (!Number.isInteger(width) || width < 1 || width > 10000) return 'width is between 1 and 10^4.';
  if (!Number.isInteger(height) || height < 1 || height > 10000) return 'height is between 1 and 10^4.';
  if (!Array.isArray(food) || food.length < 1 || food.length > 50) return 'food needs 1 to 50 pieces.';
  if (food.some(f => !Array.isArray(f) || f.length !== 2 || !Number.isInteger(f[0]) || !Number.isInteger(f[1]) || f[0] < 0 || f[0] >= height || f[1] < 0 || f[1] >= width)) return 'Each piece of food is a [row, col] cell on the board.';
  if (operations.length - 1 > 10000) return 'At most 10^4 calls to move.';
  // Replay the game to check that food never appears on the snake and nothing follows a game over.
  const body = [[0, 0]];
  const occupied = new Set(['0,0']);
  if (occupied.has(food[0].join())) return 'Food cannot appear on a cell the snake covers.';
  let eaten = 0, over = false;
  for (let i = 1; i < operations.length; i++) {
    if (operations[i] !== 'move' || !Array.isArray(args[i]) || args[i].length !== 1 || !['U', 'D', 'L', 'R'].includes(args[i][0])) return "Each call is move with 'U', 'D', 'L' or 'R'.";
    if (over) return 'No move can follow a move that ended the game.';
    const [row, col] = body[body.length - 1];
    const d = args[i][0];
    const r = row + (d === 'U' ? -1 : d === 'D' ? 1 : 0), c = col + (d === 'L' ? -1 : d === 'R' ? 1 : 0);
    if (r < 0 || r >= height || c < 0 || c >= width) { over = true; continue; }
    const eats = eaten < food.length && food[eaten][0] === r && food[eaten][1] === c;
    if (eats) eaten++;
    else occupied.delete(body.shift().join());
    if (occupied.has(r + ',' + c)) { over = true; continue; }
    body.push([r, c]);
    occupied.add(r + ',' + c);
    if (eats && eaten < food.length && occupied.has(food[eaten].join())) return 'Food cannot appear on a cell the snake covers.';
  }
  return null;
}

