class SnakeGame {
  constructor(width, height, food) {
    this.width = width;
    this.height = height;
    this.food = food;
    this.foodIndex = 0;
    this.body = [[0, 0]];
    this.occupied = new Set([0]);
    this.steps = new Map([
      ['U', [-1, 0]],
      ['D', [1, 0]],
      ['L', [0, -1]],
      ['R', [0, 1]],
    ]);
  }

  move(direction) {
    const [row, col] = this.body[this.body.length - 1];
    const [dRow, dCol] = this.steps.get(direction);
    const nextRow = row + dRow;
    const nextCol = col + dCol;
    if (nextRow < 0 || nextRow >= this.height || nextCol < 0 || nextCol >= this.width) {
      return -1;
    }
    const meal = this.food[this.foodIndex];
    if (this.foodIndex < this.food.length && meal[0] === nextRow && meal[1] === nextCol) {
      this.foodIndex++;
    } else {
      const [tailRow, tailCol] = this.body.shift();
      this.occupied.delete(tailRow * this.width + tailCol);
    }
    const key = nextRow * this.width + nextCol;
    if (this.occupied.has(key)) {
      return -1;
    }
    this.body.push([nextRow, nextCol]);
    this.occupied.add(key);
    return this.foodIndex;
  }
}

