class SnakeGame {
  constructor(width, height, food) {
    this.width = width;
    this.height = height;
    this.food = food;
    this.cells = [[0, 0]]; // head first
    this.score = 0;
  }
  move(direction) {
    const [row, col] = this.cells[0];
    const next = direction === 'U' ? [row - 1, col] : direction === 'D' ? [row + 1, col] : direction === 'L' ? [row, col - 1] : [row, col + 1];
    if (next[0] < 0 || next[0] >= this.height || next[1] < 0 || next[1] >= this.width) return -1;
    const meal = this.food[this.score];
    const eats = meal !== undefined && meal[0] === next[0] && meal[1] === next[1];
    // Without food the last cell is dropped before checking for a collision.
    const kept = eats ? this.cells : this.cells.slice(0, -1);
    if (kept.some(([r, c]) => r === next[0] && c === next[1])) return -1;
    this.cells = [next, ...kept];
    if (eats) this.score++;
    return this.score;
  }
}

