function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const large = size === 'large';
  let width, height;
  do {
    width = large ? 5 + pick(36) : 1 + pick(5);
    height = large ? 5 + pick(36) : 1 + pick(5);
  } while (width * height < 2);
  const foodCount = large ? 20 + pick(31) : 1 + pick(6);
  const moveCount = large ? 499 : 1 + pick(14);
  const careful = large ? 0.995 : 0.6;
  const key = (r, c) => r * width + c;
  const body = [[0, 0]];
  const occupied = new Set([0]);
  const freeCell = () => {
    const free = [];
    for (let r = 0; r < height; r++) for (let c = 0; c < width; c++) if (!occupied.has(key(r, c))) free.push([r, c]);
    return free.length ? free[pick(free.length)] : null;
  };
  // Food is placed when it appears, on a cell the snake does not cover at that moment.
  const food = [freeCell()];
  let placing = true;
  let eaten = 0;
  const steps = { U: [-1, 0], D: [1, 0], L: [0, -1], R: [0, 1] };
  const names = ['U', 'D', 'L', 'R'];
  const moves = [];
  for (let m = 0; m < moveCount; m++) {
    const [row, col] = body[body.length - 1];
    const target = eaten < food.length ? food[eaten] : null;
    const outcome = name => {
      const r = row + steps[name][0], c = col + steps[name][1];
      if (r < 0 || r >= height || c < 0 || c >= width) return null;
      const eats = target !== null && target[0] === r && target[1] === c;
      const tail = body[0];
      if (occupied.has(key(r, c)) && (eats || key(tail[0], tail[1]) !== key(r, c))) return null;
      return { r, c, eats };
    };
    let name = names[pick(4)];
    if (rand() < careful) {
      const safe = names.filter(n => outcome(n) !== null);
      if (safe.length) {
        const gap = n => { const o = outcome(n); return target ? Math.abs(o.r - target[0]) + Math.abs(o.c - target[1]) : 0; };
        const best = Math.min(...safe.map(gap));
        const good = rand() < 0.7 ? safe.filter(n => gap(n) === best) : safe;
        name = good[pick(good.length)];
      }
    }
    moves.push(name);
    const result = outcome(name);
    if (result === null) break; // the game is over, so no more moves follow
    if (result.eats) {
      eaten++;
    } else {
      const [tailRow, tailCol] = body.shift();
      occupied.delete(key(tailRow, tailCol));
    }
    body.push([result.r, result.c]);
    occupied.add(key(result.r, result.c));
    if (result.eats && placing && food.length < foodCount) {
      const cell = freeCell();
      if (cell) food.push(cell);
      else placing = false;
    }
  }
  // Pieces queued behind a piece that is still waiting never appear, so they can go anywhere.
  while (placing && food.length > eaten && food.length < foodCount) food.push([pick(height), pick(width)]);
  return [["SnakeGame", ...moves.map(() => 'move')], [[width, height, food], ...moves.map(m => [m])]];
}
